package chart

import (
	"fmt"
	"html"
	"math"
	"strings"
)

// RenderSVG renders a chart to escaped SVG. The SVG is generated by the
// tooling (trusted), not from user input, so it's safe. Labels are escaped.
func RenderBarSVG(c Bar) string {
	width := 600
	height := 400
	margin := 60

	var buf strings.Builder
	fmt.Fprintf(&buf, `<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 %d %d">`, width, height, width, height)
	buf.WriteString("\n")

	if c.Title != "" {
		fmt.Fprintf(&buf, `<text x="%d" y="30" text-anchor="middle" font-size="16">%s</text>`, width/2, html.EscapeString(c.Title))
		buf.WriteString("\n")
	}

	if len(c.Labels) == 0 || len(c.Series) == 0 {
		buf.WriteString("</svg>")
		return buf.String()
	}

	// Find max value for scaling.
	maxVal := 0.0
	for _, s := range c.Series {
		for _, v := range s.Values {
			if v > maxVal {
				maxVal = v
			}
		}
	}
	if maxVal == 0 {
		maxVal = 1
	}

	chartW := float64(width - 2*margin)
	chartH := float64(height - 2*margin)
	barW := chartW / float64(len(c.Labels)) / float64(len(c.Series)+1)

	colors := []string{"#4e79a7", "#f28e2b", "#e15759", "#76b7b2", "#59a14f", "#edc948"}

	for si, s := range c.Series {
		color := colors[si%len(colors)]
		for li, v := range s.Values {
			barH := (v / maxVal) * chartH
			x := float64(margin) + float64(li)*chartW/float64(len(c.Labels)) + float64(si)*barW
			y := float64(margin) + chartH - barH
			fmt.Fprintf(&buf, `<rect x="%.1f" y="%.1f" width="%.1f" height="%.1f" fill="%s"/>`, x, y, barW*0.9, barH, color)
			buf.WriteString("\n")
		}
	}

	// X-axis labels.
	for i, label := range c.Labels {
		x := float64(margin) + float64(i)*chartW/float64(len(c.Labels)) + chartW/float64(len(c.Labels))/2
		y := float64(height - margin/2)
		fmt.Fprintf(&buf, `<text x="%.1f" y="%.1f" text-anchor="middle" font-size="12">%s</text>`, x, y, html.EscapeString(label))
		buf.WriteString("\n")
	}

	buf.WriteString("</svg>")
	return buf.String()
}

// RenderLineSVG renders a line chart to SVG.
func RenderLineSVG(c Line) string {
	width := 600
	height := 400
	margin := 60

	var buf strings.Builder
	fmt.Fprintf(&buf, `<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 %d %d">`, width, height, width, height)
	buf.WriteString("\n")

	if c.Title != "" {
		fmt.Fprintf(&buf, `<text x="%d" y="30" text-anchor="middle" font-size="16">%s</text>`, width/2, html.EscapeString(c.Title))
		buf.WriteString("\n")
	}

	if len(c.X) == 0 || len(c.Series) == 0 {
		buf.WriteString("</svg>")
		return buf.String()
	}

	// Find ranges.
	minX, maxX := c.X[0], c.X[0]
	maxY := 0.0
	for _, v := range c.X {
		minX = math.Min(minX, v)
		maxX = math.Max(maxX, v)
	}
	for _, s := range c.Series {
		for _, v := range s.Values {
			maxY = math.Max(maxY, math.Abs(v))
		}
	}
	if maxX == minX {
		maxX = minX + 1
	}
	if maxY == 0 {
		maxY = 1
	}

	chartW := float64(width - 2*margin)
	chartH := float64(height - 2*margin)
	colors := []string{"#4e79a7", "#f28e2b", "#e15759", "#76b7b2", "#59a14f"}

	for si, s := range c.Series {
		color := colors[si%len(colors)]
		var points []string
		for i, v := range s.Values {
			x := float64(margin) + (c.X[i]-minX)/(maxX-minX)*chartW
			y := float64(margin) + chartH - (v/maxY)*chartH
			points = append(points, fmt.Sprintf("%.1f,%.1f", x, y))
		}
		fmt.Fprintf(&buf, `<polyline points="%s" fill="none" stroke="%s" stroke-width="2"/>`, strings.Join(points, " "), color)
		buf.WriteString("\n")
	}

	buf.WriteString("</svg>")
	return buf.String()
}

// RenderPieSVG renders a pie chart to SVG.
func RenderPieSVG(c Pie) string {
	width := 400
	height := 400
	cx, cy := float64(width)/2, float64(height)/2
	radius := 150.0

	var buf strings.Builder
	fmt.Fprintf(&buf, `<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 %d %d">`, width, height, width, height)
	buf.WriteString("\n")

	if c.Title != "" {
		fmt.Fprintf(&buf, `<text x="%d" y="25" text-anchor="middle" font-size="16">%s</text>`, width/2, html.EscapeString(c.Title))
		buf.WriteString("\n")
	}

	total := 0.0
	for _, v := range c.Values {
		total += v
	}
	if total == 0 {
		buf.WriteString("</svg>")
		return buf.String()
	}

	colors := []string{"#4e79a7", "#f28e2b", "#e15759", "#76b7b2", "#59a14f", "#edc948", "#b07aa1", "#ff9da7"}
	startAngle := -math.Pi / 2

	for i, v := range c.Values {
		angle := (v / total) * 2 * math.Pi
		endAngle := startAngle + angle
		x1 := cx + radius*math.Cos(startAngle)
		y1 := cy + radius*math.Sin(startAngle)
		x2 := cx + radius*math.Cos(endAngle)
		y2 := cy + radius*math.Sin(endAngle)
		largeArc := 0
		if angle > math.Pi {
			largeArc = 1
		}
		color := colors[i%len(colors)]
		fmt.Fprintf(&buf, `<path d="M%.1f,%.1f L%.1f,%.1f A%.1f,%.1f 0 %d,1 %.1f,%.1f Z" fill="%s"/>`,
			cx, cy, x1, y1, radius, radius, largeArc, x2, y2, color)
		buf.WriteString("\n")
		startAngle = endAngle
	}

	buf.WriteString("</svg>")
	return buf.String()
}
